#!/bin/bash

# Download Acqua yacht images with JWT tokens

count=1
while IFS= read -r url; do
    if [ ! -z "$url" ]; then
        echo "Downloading image $count..."
        curl -s "$url" -o "public/images/yachts/acqua/$count.jpg"
        
        # Check if file size is at least 5KB
        if [ -f "public/images/yachts/acqua/$count.jpg" ]; then
            size=$(stat -f%z "public/images/yachts/acqua/$count.jpg" 2>/dev/null || stat -c%s "public/images/yachts/acqua/$count.jpg" 2>/dev/null)
            if [ $size -lt 5120 ]; then
                echo "Image $count is too small ($size bytes), removing..."
                rm "public/images/yachts/acqua/$count.jpg"
            else
                echo "Image $count downloaded successfully ($size bytes)"
                count=$((count + 1))
            fi
        fi
    fi
done << 'EOF'
